<?php
if (!defined('ABSPATH')) exit; function gc_register_chapter_leader_role(){ if(!get_role('chapter_leader')) add_role('chapter_leader','Chapter Leader',array('read'=>true)); } add_action('init','gc_register_chapter_leader_role'); function gc_chapter_application_fields(){ return array('name','email','phone','state','capital','about'); } function gc_handle_chapter_application(){ if(empty($_POST['gc_chapter_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['gc_chapter_nonce'])),'gc_chapter_apply')) wp_die('Security check failed.',403); $redirect=gc_page_url('start-a-chapter'); $name=sanitize_text_field(wp_unslash($_POST['gc_name']??'')); $email=sanitize_email(wp_unslash($_POST['gc_email']??'')); $phone=sanitize_text_field(wp_unslash($_POST['gc_phone']??'')); $state=sanitize_text_field(wp_unslash($_POST['gc_state']??'')); $capital=sanitize_text_field(wp_unslash($_POST['gc_capital']??'')); $about=sanitize_textarea_field(wp_unslash($_POST['gc_about']??'')); if(!$name || !is_email($email) || !$state){ wp_safe_redirect(add_query_arg('gc_chapter','error',$redirect)); exit; } $id=wp_insert_post(array('post_type'=>'gc_submission','post_status'=>'private','post_title'=>$name.' — Chapter Application')); if(!$id || is_wp_error($id)) wp_die('Could not save application.',500); update_post_meta($id,'gc_form_type_label','Start a Chapter'); update_post_meta($id,'gc_email',$email); update_post_meta($id,'gc_phone',$phone); update_post_meta($id,'gc_workflow_status','new'); update_post_meta($id,'gc_workflow_name',$name); update_post_meta($id,'gc_workflow_state',$state); update_post_meta($id,'gc_workflow_capital',$capital); update_post_meta($id,'gc_workflow_about',$about); $admin=gc_contact_email(); $subject='New Chapter Application — Game Changers Nigeria'; wp_mail($admin,$subject,"Name: $name\nEmail: $email\nPhone: $phone\nState: $state\nCapital: $capital\n\nAbout the proposed chapter:\n$about",array('Reply-To: '.$name.' <'.$email.'>')); wp_mail($email,'We received your Chapter Application — Game Changers Nigeria',"Hello $name,\n\nWe received your application to start a Game Changers Nigeria chapter in $state. The team will review it and email you after approval.\n\nThank you,\nGame Changers Nigeria"); wp_safe_redirect(add_query_arg('gc_chapter','sent',$redirect)); exit; } add_action('admin_post_gc_chapter_apply','gc_handle_chapter_application'); add_action('admin_post_nopriv_gc_chapter_apply','gc_handle_chapter_application'); function gc_chapter_approval_on_save($post_id){ if(get_post_type($post_id)!=='gc_submission' || wp_is_post_revision($post_id) || !current_user_can('edit_post',$post_id)) return; $type=get_post_meta($post_id,'gc_form_type_label',true); if($type!=='Start a Chapter') return; if(get_post_meta($post_id,'gc_chapter_approved_done',true)) return; $status=get_post_meta($post_id,'gc_workflow_status',true); if($status!=='accepted') return; $email=sanitize_email(get_post_meta($post_id,'gc_email',true)); $name=sanitize_text_field(get_post_meta($post_id,'gc_workflow_name',true)); $state=sanitize_text_field(get_post_meta($post_id,'gc_workflow_state',true)); if(!$email || !$name) return; $user=get_user_by('email',$email); if(!$user){ $uid=wp_create_user(sanitize_user(strtolower(preg_replace('/[^a-z0-9]/i','.', $name)),true),wp_generate_password(24,true,true),$email); if(is_wp_error($uid)) return; $user=get_user_by('id',$uid); } if(!$user) return; $user->add_role('chapter_leader'); update_user_meta($user->ID,'gc_chapter_leader_approved',1); update_user_meta($user->ID,'gc_chapter_leader_state',$state); update_user_meta($user->ID,'gc_chapter_leader_submission',$post_id); $reset=get_password_reset_key($user); $link=!is_wp_error($reset)?network_site_url('wp-login.php?action=rp&key='.rawurlencode($reset).'&login='.rawurlencode($user->user_login),'login') : gc_page_url('chapter-login'); wp_mail($email,'Your Chapter Leader Application is Approved — Game Changers Nigeria',"Hello $name,\n\nYour application to start a Game Changers Nigeria chapter has been approved.\n\nLogin: $link\n\nAfter logging in, open your Chapter Leader Dashboard to create/manage your chapter, add the chapter description and WhatsApp link.\n\nWelcome to the movement."); update_post_meta($post_id,'gc_chapter_approved_done',1); update_post_meta($post_id,'gc_chapter_leader_user_id',$user->ID); } add_action('save_post_gc_submission','gc_chapter_approval_on_save',20); function gc_chapter_leader_allowed(){ $u=wp_get_current_user(); return $u && $u->exists() && (current_user_can('manage_options') || in_array('chapter_leader',(array)$u->roles,true)) && get_user_meta($u->ID,'gc_chapter_leader_approved',true); } function gc_handle_chapter_leader_save(){ if(!gc_chapter_leader_allowed() || empty($_POST['gc_leader_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['gc_leader_nonce'])),'gc_leader_save')) wp_die('Not authorised.',403); $u=wp_get_current_user(); $state=sanitize_text_field(wp_unslash($_POST['gc_state']??'')); $map=gc_ng_state_capitals(); if(!isset($map[$state])) wp_die('Please select a valid state.',400); $capital=$map[$state]; $title=sanitize_text_field(wp_unslash($_POST['gc_title']??($state.' Chapter'))); $about=wp_kses_post(wp_unslash($_POST['gc_about']??'')); $wa=esc_url_raw(wp_unslash($_POST['gc_whatsapp']??'')); $cid=(int)get_user_meta($u->ID,'gc_chapter_leader_chapter_id',true); if(!$cid){ $found=get_posts(array('post_type'=>'gc_chapter','post_status'=>'publish','posts_per_page'=>1,'meta_query'=>array(array('key'=>'gc_chapter_state','value'=>$state)))); $cid=$found? $found[0]->ID:0; } if($cid) wp_update_post(array('ID'=>$cid,'post_title'=>$title,'post_content'=>$about)); else $cid=wp_insert_post(array('post_type'=>'gc_chapter','post_status'=>'publish','post_title'=>$title,'post_content'=>$about)); if($cid && !is_wp_error($cid)){ update_post_meta($cid,'gc_chapter_state',$state); update_post_meta($cid,'gc_chapter_capital',$capital); update_post_meta($cid,'gc_whatsapp_link',$wa); update_post_meta($cid,'gc_chapter_leader_user_id',$u->ID); update_user_meta($u->ID,'gc_chapter_leader_chapter_id',$cid); } wp_safe_redirect(add_query_arg('gc_chapter','saved',wp_get_referer()?:gc_page_url('chapter-dashboard'))); exit; } add_action('admin_post_gc_chapter_leader_save','gc_handle_chapter_leader_save'); function gc_chapter_leader_admin_notice(){ if(!is_user_logged_in()||!gc_chapter_leader_allowed()) return; } 